def _strip_model_prefixes(feature: str) -> str:
    """Remove representation wrappers while keeping the physical feature body visible."""
    s = str(feature)
    changed = True
    while changed:
        changed = False
        for prefix in ("LEGACY__", "INV__"):
            if s.startswith(prefix):
                s = s[len(prefix):]
                changed = True
    return s

def _lower(feature: str) -> str:
    return _strip_model_prefixes(feature).lower()

def _contains_any(text: str, tokens) -> bool:
    return any(tok.lower() in text.lower() for tok in tokens)

def _is_variable_3p2_endpoint_related(body: str) -> bool:
    """NASA RW cells discharge to 3.2 V, so 3.2-V landmarks are endpoint-contaminated."""
    b = body.lower()
    if "3p2" not in b:
        return False
    return _contains_any(b, [
        "timet o", # harmless typo guard; the real token below is what matters
        "timeto_", "capacityto_", "energyto_",
        "timeratio_", "capacityratio_", "energyratio_",
        "partialaveragevoltageto_",
    ])

def classify_feature(feature: str, protocol: str) -> dict:
    """
    Conservative information-availability classification.

    protocol: CONSTANT or VARIABLE
    """
    f = str(feature)
    body = _strip_model_prefixes(f)
    b = body.lower()
    protocol = str(protocol).upper()

    flags = []
    reason = ""
    family = "OTHER"
    requires_full_cycle_signal = False
    requires_trivial_baseline = False

    # ------------------------------------------------------------------
    # 1) Strictly previous-cycle features: secondary history setting only.
    # ------------------------------------------------------------------
    if "pastonly" in b:
        family = "PREVIOUS_CYCLE_HISTORY"
        flags.append("USES_PREVIOUS_COMPLETED_CYCLE")
        return {
            "Classification": HISTORY,
            "Family": family,
            "Reason": (
                "Strictly previous-cycle feature. Causal with respect to cycle t, but it uses "
                "information from a completed earlier cycle and therefore belongs in a separately "
                "reported history-assisted setting rather than the primary capacity-blind setting."
            ),
            "Flags": " | ".join(flags),
            "Requires_Full_Cycle_Signal": True,
            "Requires_Trivial_Baseline": False,
        }

    # ------------------------------------------------------------------
    # 2) Dataset/source identity and explicit target-like metadata.
    # ------------------------------------------------------------------
    if b in {"source_is_nasa", "protocol", "calculated_soh(%)", "soh", "target"}:
        return {
            "Classification": INADMISSIBLE,
            "Family": "IDENTITY_OR_TARGET",
            "Reason": "Dataset/protocol identity or target-like metadata is not an admissible predictor.",
            "Flags": "SOURCE_OR_TARGET_SHORTCUT",
            "Requires_Full_Cycle_Signal": False,
            "Requires_Trivial_Baseline": False,
        }

    # ------------------------------------------------------------------
    # 3) Variable-protocol 3.2-V endpoint contamination.
    # ------------------------------------------------------------------
    if protocol == "VARIABLE" and _is_variable_3p2_endpoint_related(body):
        return {
            "Classification": INADMISSIBLE,
            "Family": "VARIABLE_3P2_ENDPOINT",
            "Reason": (
                "For NASA random-walk cells, discharge terminates at 3.2 V. A 3.2-V time/capacity/"
                "energy landmark (or a ratio derived from it) therefore coincides with or depends on "
                "the discharge endpoint and can reproduce the capacity-based SoH target."
            ),
            "Flags": "NASA_RW_3P2_ENDPOINT",
            "Requires_Full_Cycle_Signal": True,
            "Requires_Trivial_Baseline": False,
        }

    # ------------------------------------------------------------------
    # 4) Direct same-cycle full-discharge totals and transformations.
    # ------------------------------------------------------------------
    direct_total_tokens = [
        "discharge_cumulativecapacity",
        "discharge_cumulativeenergy",
        "discharge_duration",
        "throughput_efc",
        "cumulative_throughput_efc",
    ]
    if _contains_any(b, direct_total_tokens):
        return {
            "Classification": INADMISSIBLE,
            "Family": "CURRENT_CYCLE_FULL_DISCHARGE_TOTAL",
            "Reason": (
                "Uses or transforms same-cycle full discharge capacity, energy, duration, or "
                "capacity-derived throughput. These quantities are too close to the capacity-based SoH target."
            ),
            "Flags": "DIRECT_OR_NEAR_DIRECT_TARGET_PROXY",
            "Requires_Full_Cycle_Signal": True,
            "Requires_Trivial_Baseline": False,
        }

    # Full-cycle scale derivatives that explicitly contain total Q/E/time.
    if _contains_any(b, [
        "discharge_voltagedropperah",
        "discharge_voltagedropperhour",
        "discharge_energyperhour",
        "discharge_averagevoltage",
    ]):
        return {
            "Classification": INADMISSIBLE,
            "Family": "FULL_CYCLE_SCALE_DERIVED",
            "Reason": (
                "Derived using same-cycle full-discharge capacity, energy, or duration. Excluded from "
                "the strict primary setting even when expressed as a ratio."
            ),
            "Flags": "USES_EXCLUDED_FULL_CYCLE_SCALE",
            "Requires_Full_Cycle_Signal": True,
            "Requires_Trivial_Baseline": False,
        }

    # Efficiencies contain same-cycle discharge capacity/energy in the numerator.
    if _contains_any(b, ["coulombic_efficiency", "energy_efficiency", "coulombicefficiency", "energyefficiency"]):
        return {
            "Classification": INADMISSIBLE,
            "Family": "EFFICIENCY_FROM_FULL_DISCHARGE",
            "Reason": (
                "Same-cycle efficiency contains full discharge capacity or energy and is therefore "
                "target-proximal for capacity-based SoH."
            ),
            "Flags": "USES_FULL_DISCHARGE_Q_OR_E",
            "Requires_Full_Cycle_Signal": True,
            "Requires_Trivial_Baseline": False,
        }

    # ------------------------------------------------------------------
    # 5) Features whose construction explicitly needs eventual current-cycle Q.
    # ------------------------------------------------------------------
    if _contains_any(b, ["discharge_voltageat_q", "discharge_timeat_q", "discharge_energyat_q"]):
        return {
            "Classification": INADMISSIBLE,
            "Family": "Q_FRACTION_LANDMARK",
            "Reason": (
                "The Q10-Q90 style landmark is defined using the eventual current-cycle total capacity, "
                "so it is unavailable without knowing the quantity the model is intended to avoid measuring."
            ),
            "Flags": "REQUIRES_EVENTUAL_CURRENT_CYCLE_Q",
            "Requires_Full_Cycle_Signal": True,
            "Requires_Trivial_Baseline": False,
        }

    # The early/middle/late masks in the current code use cumulative_q / total_q
    # when total_q is finite. This hidden dependency must be treated conservatively.
    if (
        _contains_any(b, [
            "discharge_voltage_early", "discharge_voltage_middle", "discharge_voltage_late",
            "discharge_current_early", "discharge_current_middle", "discharge_current_late",
            "discharge_lateminusearlyvoltage",
        ])
    ):
        return {
            "Classification": INADMISSIBLE,
            "Family": "Q_NORMALIZED_PHASE_FEATURE",
            "Reason": (
                "The current implementation defines early/middle/late discharge phases using cumulative "
                "capacity divided by eventual total cycle capacity when available. The feature therefore "
                "depends on the excluded current-cycle total Q even if its final value is a voltage/current statistic."
            ),
            "Flags": "HIDDEN_EVENTUAL_Q_DEPENDENCE",
            "Requires_Full_Cycle_Signal": True,
            "Requires_Trivial_Baseline": False,
        }

    # Full Step-7 duration/energy are direct discharge-scale proxies.
    if "discharge_step7" in b and _contains_any(b, ["duration", "energy", "tinv"]):
        return {
            "Classification": INADMISSIBLE,
            "Family": "STEP7_FULL_DISCHARGE_SCALE",
            "Reason": (
                "Step-7 discharge duration/energy (or inverse duration) is a strong same-cycle full-discharge "
                "scale proxy and is excluded from the strict primary setting."
            ),
            "Flags": "FULL_DISCHARGE_STEP_SCALE",
            "Requires_Full_Cycle_Signal": True,
            "Requires_Trivial_Baseline": False,
        }

    # ------------------------------------------------------------------
    # 6) Same-cycle fixed-voltage landmarks: secondary partial-observation setting.
    # ------------------------------------------------------------------
    if _contains_any(b, ["discharge_timeto_", "discharge_capacityto_", "discharge_energyto_"]):
        family = "FIXED_VOLTAGE_PARTIAL_LANDMARK"
        return {
            "Classification": PARTIAL,
            "Family": family,
            "Reason": (
                "Same-cycle fixed-voltage time/capacity/energy measurement. It can be evaluated before "
                "end-of-discharge when the threshold is genuinely pre-endpoint, but it should be reported "
                "as a separate partial-observation setting rather than the strict capacity-blind primary model."
            ),
            "Flags": "SAME_CYCLE_PARTIAL_MEASUREMENT",
            "Requires_Full_Cycle_Signal": False,
            "Requires_Trivial_Baseline": False,
        }

    # Run 5E ratios/partial average voltage inherit fixed-voltage information.
    if _contains_any(b, [
        "r5e_norm__timeratio_", "r5e_norm__capacityratio_", "r5e_norm__energyratio_",
        "r5e_norm__partialaveragevoltageto_",
    ]):
        return {
            "Classification": PARTIAL,
            "Family": "RUN5E_PARTIAL_LANDMARK_DERIVED",
            "Reason": (
                "Derived from same-cycle fixed-voltage time/capacity/energy landmarks. Retain only in the "
                "separately reported partial-observation setting."
            ),
            "Flags": "DERIVED_FROM_PARTIAL_LANDMARK",
            "Requires_Full_Cycle_Signal": False,
            "Requires_Trivial_Baseline": False,
        }

    # ------------------------------------------------------------------
    # 7) Incremental-capacity features: manual decision before strict freeze.
    # ------------------------------------------------------------------
    if "_ic_" in b or b.endswith("_ic") or "incrementalcapacity" in b:
        return {
            "Classification": REVIEW,
            "Family": "INCREMENTAL_CAPACITY",
            "Reason": (
                "Incremental-capacity descriptors are based on integrated charge/discharge quantity versus voltage. "
                "They are not automatically equivalent to total discharge capacity, but they are capacity-derived "
                "and should be explicitly accepted or excluded before freezing the strict primary feature policy."
            ),
            "Flags": "CAPACITY_DERIVED_SHAPE_FEATURE",
            "Requires_Full_Cycle_Signal": "discharge" in b,
            "Requires_Trivial_Baseline": False,
        }

    # ------------------------------------------------------------------
    # 8) Charge-side integrated totals/durations: not target leakage by definition,
    #    but sufficiently close to capacity measurement to require an explicit choice.
    # ------------------------------------------------------------------
    if "charge_" in b and _contains_any(b, [
        "cumulativecapacity", "cumulativeenergy", "duration", "_energy", "timetofull", "timet o"
    ]):
        return {
            "Classification": REVIEW,
            "Family": "CHARGE_SIDE_INTEGRATED_MEASUREMENT",
            "Reason": (
                "Uses same-cycle integrated charge/energy or charge duration. This is not the discharge-capacity "
                "target itself, but it can be a strong capacity proxy and should be explicitly justified or moved "
                "to an assisted-measurement setting."
            ),
            "Flags": "CHARGE_CAPACITY_OR_DURATION_PROXY",
            "Requires_Full_Cycle_Signal": True,
            "Requires_Trivial_Baseline": False,
        }

    # ------------------------------------------------------------------
    # 9) Age coordinates are not capacity leakage, but must face a trivial baseline.
    # ------------------------------------------------------------------
    if b in {"cycle_index", "cycle_age", "log_cycle_age"} or _contains_any(b, ["__cycle_age", "__log_cycle_age"]):
        requires_trivial_baseline = True
        return {
            "Classification": STRICT_SAFE,
            "Family": "AGE_COORDINATE",
            "Reason": (
                "Does not directly use capacity, but it can act as a strong degradation shortcut. It may be retained "
                "only if the revised paper reports an explicit age-only baseline and discusses transfer limitations."
            ),
            "Flags": "REQUIRES_AGE_ONLY_BASELINE",
            "Requires_Full_Cycle_Signal": False,
            "Requires_Trivial_Baseline": True,
        }

    # ------------------------------------------------------------------
    # 10) Default: raw-signal/resistance/shape feature with no detected direct
    #     capacity/energy/endpoint dependency.
    # ------------------------------------------------------------------
    if "discharge_" in b or "delta" in b or "dvdt" in b:
        requires_full_cycle_signal = True

    if "internal_resistance" in b:
        family = "RESISTANCE"
    elif "dvdt" in b or "dynamic" in b:
        family = "DYNAMIC_RESPONSE"
    elif "r5e_norm" in b:
        family = "RUN5E_LOAD_NORMALIZED_SIGNAL"
    elif "voltage" in b or "current" in b:
        family = "VOLTAGE_CURRENT_SHAPE"
    elif "charge_" in b:
        family = "CHARGE_SIGNAL"
    elif "discharge_" in b:
        family = "DISCHARGE_SIGNAL"
    else:
        family = "OTHER_SIGNAL"

    return {
        "Classification": STRICT_SAFE,
        "Family": family,
        "Reason": (
            "No rule detected direct current-cycle total capacity/energy/duration, endpoint-capacity reuse, "
            "or strictly previous-cycle full-capacity information. Retained provisionally for the strict primary model."
        ),
        "Flags": "",
        "Requires_Full_Cycle_Signal": bool(requires_full_cycle_signal),
        "Requires_Trivial_Baseline": bool(requires_trivial_baseline),
    }

def feature_coverage_record(df: pd.DataFrame, feature: str, group_col: str, source_col: str):
    if feature not in df.columns:
        return {
            "Overall_Finite_Coverage": 0.0,
            "N_Batteries_With_Any": 0,
            "N_Batteries_Total": int(df[group_col].nunique()),
            "Min_Battery_Finite_Coverage": 0.0,
            "Median_Battery_Finite_Coverage": 0.0,
            "CALCE_Finite_Coverage": np.nan,
            "NASA_Finite_Coverage": np.nan,
        }

    x = pd.to_numeric(df[feature], errors="coerce")
    finite = x.notna()
    tmp = pd.DataFrame({
        group_col: df[group_col].astype(str),
        source_col: df[source_col].astype(str),
        "finite": finite.astype(float),
    })
    batt = tmp.groupby(group_col)["finite"].mean()
    src = tmp.groupby(source_col)["finite"].mean()
    return {
        "Overall_Finite_Coverage": float(finite.mean()),
        "N_Batteries_With_Any": int((batt > 0).sum()),
        "N_Batteries_Total": int(len(batt)),
        "Min_Battery_Finite_Coverage": float(batt.min()) if len(batt) else np.nan,
        "Median_Battery_Finite_Coverage": float(batt.median()) if len(batt) else np.nan,
        "CALCE_Finite_Coverage": float(src.get("CALCE", np.nan)),
        "NASA_Finite_Coverage": float(src.get("NASA", np.nan)),
    }

def build_audit(df, features, protocol, group_col, source_col, current_allowed_set, source_label):
    rows = []
    current_allowed_set = set(current_allowed_set)
    for f in sorted(dict.fromkeys(features)):
        cls = classify_feature(f, protocol)
        cov = feature_coverage_record(df, f, group_col, source_col)
        recommended = cls["Classification"] == STRICT_SAFE
        rows.append({
            "Feature": f,
            "Protocol": protocol,
            "Current_Source": source_label,
            "Current_Model_Candidate": f in current_allowed_set,
            "Recommended_Primary_Strict": recommended,
            "Recommended_Partial_Assisted": cls["Classification"] in {STRICT_SAFE, PARTIAL},
            "Recommended_History_Assisted": cls["Classification"] in {STRICT_SAFE, HISTORY},
            "Manual_Review_Required": cls["Classification"] == REVIEW,
            **cls,
            **cov,
        })
    out = pd.DataFrame(rows)
    if not out.empty:
        out["Current_But_Not_Strict"] = out["Current_Model_Candidate"] & ~out["Recommended_Primary_Strict"]
    return out

def battery_coverage(df, features, protocol, group_col, source_col):
    rows = []
    for battery, bdf in df.groupby(group_col, sort=True):
        source = str(bdf[source_col].iloc[0]) if len(bdf) else ""
        for f in sorted(dict.fromkeys(features)):
            if f in bdf.columns:
                x = pd.to_numeric(bdf[f], errors="coerce")
                coverage = float(x.notna().mean())
                n_finite = int(x.notna().sum())
            else:
                coverage = 0.0
                n_finite = 0
            rows.append({
                "Protocol": protocol,
                "Battery": str(battery),
                "Source": source,
                "Feature": f,
                "Finite_Coverage": coverage,
                "N_Finite": n_finite,
                "N_Rows": int(len(bdf)),
            })
    return pd.DataFrame(rows)

def audit_frozen_candidates(frame: pd.DataFrame, protocol: str, group_col: str, source_col: str) -> pd.DataFrame:
    """Audit the exact candidate space used when the revision policy was frozen."""
    protocol = protocol.upper()
    features = (
        AUDITED_CURRENT_CONSTANT_FEATURES
        if protocol == "CONSTANT"
        else AUDITED_CURRENT_VARIABLE_FEATURES
    )
    return build_audit(
        df=frame,
        features=features,
        protocol=protocol,
        group_col=group_col,
        source_col=source_col,
        current_allowed_set=set(features),
        source_label="frozen-candidate-space",
    )


def assert_manuscript_audit_counts(audit: pd.DataFrame, protocol: str) -> None:
    """Fail if the frozen policy no longer reproduces the manuscript counts."""
    expected = EXPECTED_AUDIT_COUNTS[protocol.upper()]
    actual = audit.groupby("Classification")["Feature"].nunique().to_dict()
    for key, value in expected.items():
        if int(actual.get(key, 0)) != int(value):
            raise AssertionError(
                f"{protocol} feature-audit count changed for {key}: "
                f"expected {value}, found {actual.get(key, 0)}"
            )
